                <div v-if="triageSplitEnabled" class="mt-3 space-y-2 rounded-lg border border-violet-200 bg-white p-3">
                  <div class="flex items-center justify-between gap-2"><div><p class="text-[11px] font-semibold text-violet-900">独立 L3 工作项清单</p><p class="mt-0.5 text-[10px] leading-4 text-violet-700">公共需求背景、确认单和价值卡仍归主线；这里只填各独立 L3 的差异。</p></div><span class="text-[10px] text-violet-600">{{ triageBranches.length }} 个</span></div>
                  <div v-for="(branch, index) in triageBranches" :key="branch.branchKey" class="rounded-lg border border-violet-100 bg-violet-50/30 p-2.5">
                    <div class="flex items-center justify-between gap-2"><p class="text-[11px] font-medium text-violet-900">独立 L3 工作项</p><button v-if="triageBranches.length > 2" type="button" class="text-[10px] text-rose-600" @click="removeTriageBranch(index)">移除</button></div>
                    <label class="mt-2 block"><span class="form-label">L3 标题 <span class="text-rose-500">*</span></span><input v-model="branch.title" class="feishu-input w-full" maxlength="300" placeholder="例如：多语言接入" /></label>
                    <div class="mt-2 grid grid-cols-2 gap-2"><label class="block"><span class="form-label">工作类型 <span class="text-rose-500">*</span></span><select v-model="branch.itemKind" class="feishu-input w-full"><option v-for="item in l3ItemKindOptions" :key="item.key" :value="item.key">{{ item.label }}</option></select></label><label class="block"><span class="form-label">价值口径</span><select v-model="branch.relationToValue" class="feishu-input w-full"><option value="shared">共用主线价值口径</option><option value="independent">独立价值口径</option></select></label></div>
                    <label class="mt-2 block"><span class="form-label">本 L3 独有范围 / 验收差异 <span class="font-normal text-gray-400">（可选）</span></span><textarea v-model="branch.difference" rows="2" maxlength="5000" class="feishu-input w-full resize-y" placeholder="只写和其他 L3 不同的范围或通过条件；公共内容只保留在主线确认单" /></label>
                    <label class="mt-2 block"><span class="form-label">依赖与前置条件 <span class="font-normal text-gray-400">（可选）</span></span><input v-model="branch.dependency" class="feishu-input w-full" maxlength="5000" placeholder="例如：依赖统一账号、接口或另一 L3" /></label>
                    <label v-if="selectedItem.status === 'converted'" class="mt-2 block"><span class="form-label">对应已有正式 L3 <span class="font-normal text-gray-400">（历史补录可选）</span></span><select v-model="branch.formalRequirementId" class="feishu-input w-full"><option value="">不指定，系统新建独立 L3</option><option v-for="requirement in selectedItem.requirements || []" :key="requirement.id" :value="requirement.id">{{ requirement.title }} · {{ requirement.id }}</option></select></label>
                  </div>
                  <button type="button" class="feishu-btn-ghost w-full justify-center text-[10px]" @click="addTriageBranch">+ 增加一个 L3</button>
                </div>
                <div v-if="selectedItem.status === 'converted'" class="mt-3 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-[11px] leading-5 text-amber-800">当前需求已完成正式立项。保存时只做历史分解补录：保留原确认单和原需求状态，不重新发送业务确认。</div>
                <div class="mt-3 rounded-lg border border-blue-200 bg-white/80 px-3 py-2 text-[11px] leading-5 text-blue-800">保存初筛后，下面会显示业务评估卡；业务评估完成后，再选择综合决策。</div>
                <button type="button" class="feishu-btn-primary mt-3 w-full justify-center" :disabled="savingEvaluation" @click="saveTriage">{{ savingEvaluation ? '保存中...' : selectedItem.status === 'converted' ? '保存历史 L3 分解' : '保存 IT 初筛' }}</button>
              </section>
              <section v-if="selectedItem.status === 'awaiting_supplement'" class="rounded-xl border-2 border-amber-200 bg-amber-50/80 p-4 shadow-md"><p class="text-xs font-semibold text-amber-900">需求资料补充</p><p class="mt-1 text-[11px] leading-5 text-amber-700">业务已经沟通过这项需求时，不再要求逐项填写问卷。发一个轻量入口，让业务补充几句话或上传附件即可。</p><button type="button" class="feishu-btn-primary mt-3 w-full justify-center text-xs" @click="openMaterialsNotify">配置资料补充链接</button></section>
              <section v-if="selectedItem.solutionType || selectedItem.status !== 'pending_evaluation'" class="rounded-xl border-2 border-sky-300 bg-sky-50/80 p-4 shadow-md"><div class="flex items-center justify-between gap-2"><p class="text-xs font-semibold text-sky-950">② 业务负责人评估</p><span class="rounded-full bg-sky-100 px-2 py-0.5 text-[10px] font-medium text-sky-700">{{ selectedItem.reviewSummary?.submitted || 0 }}/{{ selectedItem.reviewSummary?.total || selectedItem.reviews.length }} 已提交</span></div><p class="mt-1 text-[11px] leading-5 text-sky-700">按组织角色指定直属领导或部门负责人。提出人如果同时承担直属领导/部门负责人角色，可以按该角色正常审批；同一人不会因两个角色重复收到评估单。</p><label class="mt-3 block"><span class="form-label">直属领导</span><select v-model="reviewAssignment.leaderUserId" class="feishu-input w-full" :disabled="contactsLoading" @focus="loadContacts()"><option value="">{{ contactsLoading ? '联系人加载中…' : '暂不指定' }}</option><option v-for="person in contactUsers" :key="'leader-' + (person.userId || person.userid || person.name)" :value="person.userId || person.userid || person.dingUserId">{{ person.name }}</option></select></label><label class="mt-3 block"><span class="form-label">部门负责人</span><select v-model="reviewAssignment.departmentUserId" class="feishu-input w-full" :disabled="contactsLoading" @focus="loadContacts()"><option value="">{{ contactsLoading ? '联系人加载中…' : '暂不指定' }}</option><option v-for="person in contactUsers" :key="'dept-' + (person.userId || person.userid || person.name)" :value="person.userId || person.userid || person.dingUserId">{{ person.name }}</option></select></label><button type="button" class="feishu-btn-primary mt-3 w-full justify-center text-xs" :disabled="assigningReviews || !canAssignReviews || contactsLoading" @click="assignReviews">{{ assigningReviews ? '发送中...' : '发送业务评估链接' }}</button><div class="mt-4 rounded-lg border border-emerald-200 bg-emerald-50/70 p-3"><p class="text-[11px] font-semibold text-emerald-900">已有业务沟通，不再重复发送</p><p class="mt-1 text-[10px] leading-4 text-emerald-800">适用于已经通过会议、群聊或私下沟通形成结论的需求。保存后不通知业务，只记录沟通证据并完成本环节。</p><div class="mt-2 grid gap-2 sm:grid-cols-2"><input v-model="businessReviewReuse.contactName" class="feishu-input" placeholder="已有沟通确认人，例如廿一" /><input v-model="businessReviewReuse.communicationDate" type="date" class="feishu-input" /><select v-model="businessReviewReuse.decision" class="feishu-input"><option v-for="item in businessReviewDecisionOptions" :key="item.key" :value="item.key">业务判断：{{ item.label }}</option></select><select v-model="businessReviewReuse.prioritySuggestion" class="feishu-input"><option v-for="item in reviewPriorityOptions" :key="item.key" :value="item.key">优先级：{{ item.label }}</option></select><select v-model="businessReviewReuse.source" class="feishu-input sm:col-span-2"><option value="会议沟通">来源：会议沟通</option><option value="群聊 / 私聊">来源：群聊 / 私聊</option><option value="线下沟通">来源：线下沟通</option><option value="其他">来源：其他</option></select></div><textarea v-model="businessReviewReuse.summary" rows="2" maxlength="5000" class="feishu-input mt-2 w-full resize-y" placeholder="记录已经沟通的业务结论、范围和优先级依据" /><p v-if="reuseBusinessReviewError" class="mt-2 rounded-md border border-rose-200 bg-rose-50 px-2.5 py-2 text-[11px] leading-5 text-rose-700">{{ reuseBusinessReviewError }}</p><button type="button" class="feishu-btn-ghost mt-2 w-full justify-center border border-emerald-300 bg-white text-emerald-700" :disabled="reusingBusinessReview" @click="reuseBusinessReview">{{ reusingBusinessReview ? '保存中...' : '复用沟通结论并完成业务评估' }}</button></div></section>
              <section id="demand-pool-decision-card" v-if="['business_review', 'review_complete', 'awaiting_confirmation', 'business_confirmed', 'ready_for_l3', 'poc'].includes(selectedItem.status)" class="rounded-xl border-2 border-indigo-300 bg-indigo-50/80 p-4 shadow-md">
                <div class="flex items-center justify-between gap-2"><p class="text-xs font-semibold text-indigo-950">③ IT 综合决策</p><span class="rounded-full bg-indigo-100 px-2 py-0.5 text-[10px] font-medium text-indigo-700">{{ selectedItem.status === 'business_review' && (selectedItem.reviewSummary?.pending || 0) > 0 ? '等待业务评估' : '可提交' }}</span></div>
                <p class="mt-1 text-[11px] leading-5 text-indigo-700">综合原始需求、IT 初筛和业务评估，决定实施、PoC、暂缓或不承接。这里不再重复让业务填表。</p>
                <div v-if="selectedItem.status === 'business_review' && (selectedItem.reviewSummary?.pending || 0) > 0" class="mt-3 rounded-lg border border-indigo-200 bg-white/80 px-3 py-2.5 text-[11px] leading-5 text-indigo-800">还有 {{ selectedItem.reviewSummary.pending }} 位评估人未提交，收到完整回执后即可形成综合决策。</div>
                <div v-if="!(selectedItem.reviewSummary?.total || 0)" class="mt-3 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2.5 text-[11px] leading-5 text-amber-800">尚未发起业务评估。若要形成“实施”结论，请先在上一张卡发送业务评估链接；PoC、暂缓或不承接可按实际情况直接判断。</div>
                <div v-if="selectedItem.l3Branches?.length" class="mt-3 rounded-lg border border-violet-200 bg-violet-50/60 p-3">
                  <div class="flex items-center justify-between gap-2"><p class="text-[11px] font-semibold text-violet-900">独立 L3 决策</p><span class="text-[10px] text-violet-600">每个独立 L3 分别确认</span></div>
                  <div class="mt-2 space-y-2"><div v-for="branch in selectedItem.l3Branches" :key="'decision-' + branch.id" class="rounded-lg border border-violet-100 bg-white p-2.5"><div class="flex items-center justify-between gap-2"><p class="text-[11px] font-medium text-violet-950">{{ branch.title }}</p><span class="text-[10px] text-violet-600">{{ branch.itemKindLabel }}</span></div><div class="mt-2 grid grid-cols-1 gap-2 sm:grid-cols-3"><label class="block sm:col-span-1"><span class="form-label">IT 结论 <span class="text-rose-500">*</span></span><select v-model="branchDecisionDraft[branch.id].decision" class="feishu-input w-full"><option value="">请选择</option><option v-for="item in decisionOptions" :key="item.key" :value="item.key">{{ item.label }}</option></select></label><label class="block sm:col-span-2"><span class="form-label">本 L3 判断说明 <span class="font-normal text-gray-400">（暂缓/不承接必填）</span></span><textarea v-model="branchDecisionDraft[branch.id].reason" rows="2" maxlength="5000" class="feishu-input w-full resize-y" placeholder="写本 L3 的实施边界、前置条件或不承接原因" /></label></div><label class="mt-2 block"><span class="form-label">本 L3 备注 <span class="font-normal text-gray-400">（可选）</span></span><input v-model="branchDecisionDraft[branch.id].notes" class="feishu-input w-full" maxlength="5000" placeholder="依赖、预计窗口、验收关注点" /></label></div></div>
                </div>
                <template v-if="selectedItem.status !== 'business_review' || (selectedItem.reviewSummary?.pending || 0) === 0">
                  <label class="mt-3 block"><span class="form-label">综合结论 <span class="text-rose-500">*</span></span><select v-model="evaluation.decision" class="feishu-input w-full"><option value="">请选择</option><option v-for="item in decisionOptions" :key="item.key" :value="item.key">{{ item.label }}</option></select></label>
                  <label class="mt-3 block"><span class="form-label">综合判断说明 <span v-if="evaluation.decision === 'defer' || evaluation.decision === 'reject'" class="text-rose-500">*</span></span><textarea v-model="evaluation.reason" rows="3" maxlength="5000" class="feishu-input w-full resize-y" :placeholder="evaluation.decision === 'implement' ? '说明为什么承接，以及业务评估中最关键的判断' : '说明综合判断、前置条件或暂缓原因'" /></label>
                  <label class="mt-3 block"><span class="form-label">范围、依赖与验收关注点 <span class="font-normal text-gray-400">（可选）</span></span><textarea v-model="evaluation.notes" rows="2" maxlength="5000" class="feishu-input w-full resize-y" placeholder="补充范围、依赖、预计时间或上线时需要关注的验收点" /></label>
                  <div v-if="evaluation.decision === 'implement'" class="mt-3 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2.5 text-[11px] leading-5 text-emerald-800">将进入下一张“正式创建 / 关联 L2/L3”卡，负责人、预计时间和验收关注点在那里确认。</div>
                  <div v-else-if="evaluation.decision === 'poc'" class="mt-3 rounded-lg border border-violet-200 bg-violet-50 px-3 py-2.5 text-[11px] leading-5 text-violet-800">下一张 PoC 卡会记录轻量结论；PoC 完成后回到本卡形成最终实施判断。</div>
                  <div v-else-if="evaluation.decision === 'defer' || evaluation.decision === 'reject'" class="mt-3 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2.5 text-[11px] leading-5 text-amber-800">需要填写判断说明，保存后该独立 L3 会停留在对应的暂缓 / 不承接状态。</div>
                  <button type="button" class="feishu-btn-primary mt-3 w-full justify-center" :disabled="savingEvaluation || (evaluation.decision === 'implement' && !(selectedItem.reviewSummary?.total || 0)) || (selectedItem.l3Branches?.length && !branchDecisionsComplete)" @click="saveDecision">{{ savingEvaluation ? '保存中...' : '保存综合决策' }}</button>
                </template>
              </section>
               <section v-if="selectedItem.status === 'awaiting_confirmation' && (!selectedItem.confirmation || selectedItem.confirmation.status === 'changes_requested')" class="rounded-xl border-2 border-cyan-200 bg-cyan-50/75 p-4 shadow-md"><p class="text-xs font-semibold text-cyan-900">上线前交付与价值确认</p><p class="mt-1 text-[11px] leading-5 text-cyan-700">一张业务确认单只确认一次。IT 负责把原始需求整理成“功能验收口径”和“上线后业务价值口径”，业务只需确认或退回，不需要重复填表。</p>
                 <div v-if="selectedItem.confirmation?.status === 'changes_requested'" class="mt-3 rounded-lg border border-rose-200 bg-rose-50 px-3 py-2 text-[11px] leading-5 text-rose-700">业务已退回上一版<span v-if="selectedItem.confirmation.confirmationComment">：{{ selectedItem.confirmation.confirmationComment }}</span>。修改后将生成新版本。</div>
                 <div class="mt-3 rounded-lg border border-cyan-100 bg-white px-3 py-2.5 text-[11px] leading-5 text-cyan-800"><p class="font-semibold text-cyan-900">业务原始需求（自动引用）</p><p class="mt-1 whitespace-pre-wrap leading-5">{{ selectedItem.description || '未填写原始需求描述' }}</p><p class="mt-1 text-[10px] text-cyan-500">下面只补充本次交付边界和验证口径，不再把这段需求重新描述一遍。</p></div>
                 <div class="mt-3 space-y-3 rounded-lg border border-cyan-100 bg-white/80 p-3">
                   <p class="text-[11px] font-semibold text-cyan-900">{{ confirmationTemplateLabel }} · 验收标准</p>
                   <label class="block"><span class="form-label">本次交付范围 <span class="font-normal text-gray-400">（可选）</span></span><textarea v-model="confirmationDraft.scope" rows="2" maxlength="10000" class="feishu-input w-full resize-y" placeholder="只写本次 L3 实际交付的边界，不要重复业务原始需求" /></label>
                   <label class="block"><span class="form-label">业务验证场景 <span class="font-normal text-gray-400">（可选）</span></span><textarea v-model="confirmationDraft.scenarios" rows="2" maxlength="10000" class="feishu-input w-full resize-y" placeholder="业务人员按什么关键路径验证，覆盖哪些典型场景" /></label>
                   <label class="block"><span class="form-label">功能验收通过标准 <span class="text-rose-500">*</span></span><textarea v-model="confirmationDraft.expected" rows="3" maxlength="10000" class="feishu-input w-full resize-y" placeholder="写清本次交付做了什么、业务怎么验证、什么情况算通过；可分三行，不写 30 天后的业务价值" /></label>
                   <div class="grid gap-3 sm:grid-cols-2"><label class="block"><span class="form-label">验收证据 <span class="font-normal text-gray-400">（可选）</span></span><textarea v-model="confirmationDraft.evidence" rows="2" maxlength="10000" class="feishu-input w-full resize-y" placeholder="截图、数据结果、流程记录或附件" /></label><label class="block"><span class="form-label">不在本次范围 <span class="font-normal text-gray-400">（可选）</span></span><textarea v-model="confirmationDraft.exclusions" rows="2" maxlength="10000" class="feishu-input w-full resize-y" placeholder="明确本次不交付的内容" /></label></div>
                   <details class="rounded-lg border border-cyan-100 px-3 py-2"><summary class="cursor-pointer text-xs font-medium text-cyan-700">补充 {{ confirmationTemplateLabel }}专项验收项</summary><div class="mt-3 grid gap-3 sm:grid-cols-2"><label v-for="field in confirmationTemplateFields" :key="field.key" class="block"><span class="form-label">{{ field.label }} <span class="font-normal text-gray-400">（可选）</span></span><textarea v-model="confirmationDraft[field.key]" rows="2" maxlength="10000" class="feishu-input w-full resize-y" :placeholder="field.placeholder" /></label></div></details>
                 </div>
                 <div class="mt-3 space-y-3 rounded-lg border border-emerald-200 bg-white/90 p-3">
                   <div><p class="text-[11px] font-semibold text-emerald-900">上线后业务价值口径</p><p class="mt-1 text-[10px] leading-4 text-emerald-700">只需填写上线后希望看到的业务变化；上线前基线和详细指标按需补充，避免与验收标准重复。</p></div>
                   <label class="block"><span class="form-label">验证方式 <span class="font-normal text-gray-400">（可选，默认结果 / 定性验证）</span></span><select v-model="confirmationDraft.valueDefinition.verificationMode" class="feishu-input w-full"><option value="quantitative">量化前后对比</option><option value="outcome">结果 / 定性验证</option></select></label>
                   <label class="block"><span class="form-label">当前做法 / 上线前业务基线 <span class="font-normal text-gray-400">（可选）</span></span><textarea v-model="confirmationDraft.valueDefinition.baselineSummary" rows="2" maxlength="10000" class="feishu-input w-full resize-y" placeholder="只写上线前怎么做、现状是什么；工作流可写人工步骤、耗时、处理量和错误情况" /></label>
                   <label class="block"><span class="form-label">上线后业务效果目标 <span class="text-rose-500">*</span></span><textarea v-model="confirmationDraft.valueDefinition.expectedSummary" rows="3" maxlength="10000" class="feishu-input w-full resize-y" placeholder="用一句话写上线后希望发生的业务变化，以及用什么现象或数据判断达到；无需先填数字" /></label>
                   <p class="rounded-lg border border-emerald-100 bg-emerald-50/50 px-3 py-2 text-[10px] leading-4 text-emerald-800">回访负责人默认使用当前填写人；如需指定其他人，可在上线后价值卡中调整。</p>
                   <template v-if="confirmationDraft.valueDefinition.verificationMode === 'quantitative'">
                     <div class="rounded-lg border border-emerald-100 bg-emerald-50/60 p-2.5"><p class="text-[10px] font-semibold text-emerald-800">{{ confirmationTemplateLabel }}推荐指标</p><div class="mt-2 flex flex-wrap gap-1.5"><button v-for="preset in confirmationMetricPresets" :key="preset.key" type="button" class="rounded-md border border-emerald-200 bg-white px-2 py-1 text-[10px] text-emerald-700 hover:border-emerald-400" @click="addConfirmationMetric(preset)">+ {{ preset.label }}</button><button type="button" class="rounded-md border border-gray-200 bg-white px-2 py-1 text-[10px] text-gray-600" @click="addConfirmationMetric()">+ 自定义指标</button></div></div>
                     <div v-for="(metric, index) in confirmationDraft.valueDefinition.metrics" :key="'confirmation-metric-' + index" class="rounded-lg border border-emerald-100 bg-emerald-50/30 p-2.5">
                       <div class="grid gap-2 sm:grid-cols-2">
                         <label class="block"><span class="form-label">指标名称 <span class="text-rose-500">*</span></span><input v-model="metric.label" maxlength="160" class="feishu-input w-full" placeholder="例如：单次处理耗时" /></label>
                         <label class="block"><span class="form-label">指标编码 <span class="text-rose-500">*</span></span><input v-model="metric.key" maxlength="160" class="feishu-input w-full" placeholder="例如：handling_time" /></label>
                         <label class="block"><span class="form-label">单位 <span class="text-rose-500">*</span></span><input v-model="metric.unit" maxlength="160" class="feishu-input w-full" placeholder="分钟/次、%、件/小时" /></label>
                         <label class="block"><span class="form-label">目标方向 <span class="text-rose-500">*</span></span><select v-model="metric.direction" class="feishu-input w-full"><option value="">请选择</option><option value="higher">数值越高越好</option><option value="lower">数值越低越好</option></select></label>
                         <label class="block"><span class="form-label">上线前数值 <span class="text-rose-500">*</span></span><input v-model="metric.baselineValue" type="number" step="any" class="feishu-input w-full" placeholder="0 也是有效值" /></label>
                         <label class="block"><span class="form-label">目标数值 <span class="text-rose-500">*</span></span><input v-model="metric.targetValue" type="number" step="any" class="feishu-input w-full" /></label>
                         <label class="block"><span class="form-label">统计周期 / 样本 <span class="text-rose-500">*</span></span><input v-model="metric.measurementWindow" maxlength="160" class="feishu-input w-full" placeholder="例如：上线前后各连续一周" /></label>
                         <label class="block"><span class="form-label">数据来源 <span class="text-rose-500">*</span></span><input v-model="metric.source" maxlength="160" class="feishu-input w-full" placeholder="系统日志、业务台账、抽样记录" /></label>
                       </div>
                       <button type="button" class="mt-2 text-[10px] text-rose-600" @click="removeConfirmationMetric(index)">移除这项指标</button>
                     </div>
                     <p v-if="!confirmationDraft.valueDefinition.metrics.length" class="rounded-lg border border-amber-100 bg-amber-50 px-3 py-2 text-[10px] leading-4 text-amber-700">量化验证至少需要一个完整指标。指标必须同时有基线值、目标值、单位、周期和数据来源。</p>
                   </template>
                   <label v-else-if="confirmationDraft.valueDefinition.verificationMode === 'outcome'" class="block"><span class="form-label">无法量化原因 <span class="font-normal text-gray-400">（可选）</span></span><textarea v-model="confirmationDraft.valueDefinition.nonQuantifiableReason" rows="2" maxlength="3000" class="feishu-input w-full resize-y" placeholder="如不使用数字，可补充说明原因；上线后仍按可观察结果验证" /></label>
                 </div>
                  <p v-if="!canCreateConfirmation" class="mt-2 text-[10px] leading-4 text-amber-700">请至少补齐“功能验收通过标准”和“上线后业务效果目标”；选择量化验证时，再补充一项完整指标。</p>
                 <button type="button" class="feishu-btn-primary mt-3 w-full justify-center text-xs" :disabled="creatingConfirmation || !canCreateConfirmation" @click="createConfirmation">{{ creatingConfirmation ? '保存中...' : '保存交付与价值确认单' }}</button></section>
               <section v-if="selectedItem.pocs?.length || (selectedItem.status === 'poc' && selectedItem.pocRequirement !== 'none')" class="rounded-xl border-2 border-violet-200 bg-violet-50/75 p-4 shadow-md">
                 <p class="text-xs font-semibold text-violet-900">PoC / AI 验证记录</p>
                 <p class="mt-1 text-[11px] leading-5 text-gray-400">不用逐项填表，直接记录结论、步骤规划，并可附流程图或截图。</p>
                 <button type="button" class="feishu-btn-primary mt-3 flex w-full justify-center text-xs" @click="openPocModal">打开轻量登记</button>
               </section>
                <section v-if="selectedItem.status === 'converted' || selectedItem.outcomeRequests?.length" class="rounded-xl border-2 border-emerald-200 bg-emerald-50/75 p-4 shadow-md">
                  <p class="text-xs font-semibold text-emerald-900">上线前目标基线</p>
                <p class="mt-1 text-[11px] leading-5 text-emerald-700">正式立项前先完成上线前交付与价值确认；上线后的 3 天回执和 30 天价值验证属于交付后的运营阶段。</p>
                  <div class="mt-3 rounded-lg border border-emerald-200 bg-white/80 px-3 py-2.5 text-[11px] leading-5 text-emerald-800">上线后 3 天回执和 30 天复盘属于后续运营阶段，会在正式交付后处理。</div>
                  <div v-if="selectedItem.outcomeRequests?.length" class="mt-3 rounded-lg border border-emerald-100 bg-white px-3 py-2.5 text-[11px] leading-5 text-emerald-800">已有历史成果记录 {{ selectedItem.outcomeRequests.length }} 条，请前往正式 L2/L3 详情查看。</div>
                  <details class="mt-3 rounded-lg border border-emerald-200 bg-white px-3 py-2.5">
                    <summary class="cursor-pointer text-[11px] font-semibold text-emerald-800">调整结构化指标（历史补录或口径修订）</summary>
                    <p class="mt-2 text-[10px] leading-4 text-emerald-700">新确认单中的基线、目标和指标会自动带入；这里只用于历史数据补录或确认后的必要修订。</p>
                    <div class="mt-3 space-y-3">
                      <div v-for="(metric, index) in valueCardForm.metrics" :key="'value-metric-' + index" class="rounded-lg border border-emerald-100 bg-emerald-50/40 p-2.5">
                        <div class="grid gap-2 sm:grid-cols-2">
                          <label class="block"><span class="form-label">指标名称</span><input v-model="metric.label" class="feishu-input w-full" placeholder="例如：单次处理耗时" /></label>
                          <label class="block"><span class="form-label">指标编码</span><input v-model="metric.key" class="feishu-input w-full" placeholder="例如：handling_time" /></label>
                          <label class="block"><span class="form-label">单位</span><input v-model="metric.unit" class="feishu-input w-full" placeholder="分钟 / 次 / %" /></label>
                          <label class="block"><span class="form-label">统计周期</span><input v-model="metric.measurementWindow" class="feishu-input w-full" placeholder="例如：上线前一周" /></label>
                          <label class="block"><span class="form-label">上线前数值</span><input v-model="metric.baselineValue" type="number" step="any" class="feishu-input w-full" placeholder="没有数字可留空" /></label>
                          <label class="block"><span class="form-label">目标数值</span><input v-model="metric.targetValue" type="number" step="any" class="feishu-input w-full" placeholder="没有目标可留空" /></label>
                          <label class="block"><span class="form-label">数据来源</span><input v-model="metric.source" class="feishu-input w-full" placeholder="业务负责人填写 / 系统报表" /></label>
                          <label class="block"><span class="form-label">目标方向</span><select v-model="metric.direction" class="feishu-input w-full"><option value="">自动判断</option><option value="higher">数值越高越好</option><option value="lower">数值越低越好</option></select></label>
                        </div>
                        <button type="button" class="mt-2 text-[10px] text-rose-600" @click="removeValueMetric(index)">移除这项指标</button>
                      </div>
                      <div class="flex flex-wrap items-center gap-2"><button type="button" class="feishu-btn-ghost text-[10px]" @click="addValueMetric">新增指标</button><span class="text-[10px] text-gray-400">上线后实际值由 30 天价值验证时填写</span></div>
                    </div>
                  </details>
                  <div class="mt-3 space-y-2 rounded-lg border border-emerald-100 bg-white p-3">
                    <label class="block"><span class="form-label">成果负责人</span><input v-model="valueCardForm.ownerName" class="feishu-input w-full" placeholder="填写负责回访和验证的人" /></label>
                    <label class="block"><span class="form-label">当前做法 / 上线前业务基线</span><textarea v-model="valueCardForm.baselineSummary" rows="2" class="feishu-input w-full resize-y" placeholder="用一句话说明上线前怎么做、当前是什么情况；没有数字也可以。" /></label>
                    <label class="block"><span class="form-label">上线后业务效果目标</span><textarea v-model="valueCardForm.expectedSummary" rows="2" class="feishu-input w-full resize-y" placeholder="上线后希望看到什么可观察的业务变化。" /></label>
                    <button type="button" class="feishu-btn-primary w-full justify-center text-xs" :disabled="savingValueCard" @click="saveValueCard">{{ savingValueCard ? '保存中...' : '保存上线前目标与指标' }}</button>
                  </div>
                </section>
               <p class="px-1 text-[11px] leading-5 text-gray-400">“实施”结论需在业务评估完成后提交；PoC 完成后会回到综合决策，暂缓或不承接可按实际情况说明。</p>
            </aside>
            <aside v-if="selectedItem.canEvaluate && selectedItem.confirmation?.status === 'confirmed' && ['awaiting_confirmation', 'business_confirmed', 'ready_for_l3'].includes(selectedItem.status) && !selectedItem.requirementId" class="h-fit rounded-xl border border-emerald-100 bg-white p-4 shadow-sm">
              <div class="flex items-center justify-between gap-2"><p class="text-xs font-semibold text-gray-800">正式创建 / 关联 L2/L3</p><span class="text-[10px] text-emerald-600">{{ selectedItem.confirmation?.status === 'confirmed' ? '验收标准已确认' : '等待业务确认' }}</span></div>
              <p v-if="selectedItem.confirmation?.status !== 'confirmed'" class="mt-2 rounded-lg border border-amber-100 bg-amber-50 px-3 py-2 text-[11px] leading-5 text-amber-700">请先发起并完成上线前交付与价值确认，确认完成后才能正式立项。</p>
              <div class="mt-3 grid grid-cols-3 items-center gap-1 rounded-lg bg-gray-50 p-1"><button type="button" @click="setConversionMode('create_l2')" :class="['rounded-md px-2 py-1.5 text-xs', conversion.mode === 'create_l2' ? 'bg-white font-medium text-emerald-700 shadow-sm' : 'text-gray-500']">新建 L2 + 初始建设</button><button type="button" @click="setConversionMode('create')" :class="['rounded-md px-2 py-1.5 text-xs', conversion.mode === 'create' ? 'bg-white font-medium text-emerald-700 shadow-sm' : 'text-gray-500']">已有 L2 下新建 L3</button><button type="button" @click="setConversionMode('link')" :class="['rounded-md px-2 py-1.5 text-xs', conversion.mode === 'link' ? 'bg-white font-medium text-emerald-700 shadow-sm' : 'text-gray-500']">关联已有 L3</button></div>
              <p class="mt-2 text-[11px] leading-5 text-gray-500">{{ conversionModeHelp }}</p>
              <template v-if="conversion.mode === 'create_l2'">
                <label class="mt-3 block"><span class="form-label">新 L2 名称</span><input v-model="conversion.projectName" class="feishu-input w-full" maxlength="300" /></label>
                <label class="mt-3 block"><span class="form-label">L2 类型 <span class="text-rose-500">*</span></span><select v-model="conversion.solutionType" class="feishu-input w-full"><option value="">请选择 L2 类型</option><option v-for="item in lifecycleSolutionTypeOptions" :key="item.key" :value="item.key">{{ item.label }}</option></select><span class="mt-1 block text-[10px] text-gray-400">已从 IT 初筛自动带入；如初筛未完成，请先返回评估环节。</span></label>
                <div class="mt-3 rounded-lg border border-emerald-100 bg-emerald-50/60 p-3"><p class="text-[11px] font-semibold text-emerald-800">初始建设 L3 会自动生成</p><p class="mt-1 text-[10px] leading-4 text-emerald-700">标题固定为“初始建设”，不会重复使用 L2 名称；下面的阶段会按 L2 类型推荐。</p><div v-if="conversionPhaseTemplates.length" class="mt-2 grid gap-2 sm:grid-cols-2"><label v-for="phase in conversionPhaseTemplates" :key="phase.phaseKey" class="flex items-start gap-2 rounded-md border border-white bg-white px-2.5 py-2 text-[11px] text-slate-700"><input v-model="conversion.phaseTemplateKeys" :value="phase.phaseKey" type="checkbox" class="mt-0.5 rounded border-gray-300 text-accent-500" /><span><span class="font-medium">{{ phase.phaseLabel }}</span><span class="mt-0.5 block text-[10px] leading-4 text-slate-400">{{ phase.description }}</span></span></label></div></div>
              </template>
              <template v-else-if="conversion.mode === 'create'">
                <label class="mt-3 block"><span class="form-label">归属 L2 <span class="text-rose-500">*</span></span><select v-model="conversion.projectId" class="feishu-input w-full"><option value="">请选择已有 L2</option><option v-for="project in projects" :key="project.id" :value="project.id">{{ project.name }} · {{ project.solutionTypeLabel || '待分类' }}</option></select></label>
                <label v-if="!conversion.splitEnabled" class="mt-3 block"><span class="form-label">L3 标题 <span class="text-rose-500">*</span></span><input v-model="conversion.title" class="feishu-input w-full" maxlength="300" placeholder="例如：告警规则优化、数据源接入" /></label>
                <label v-if="!conversion.splitEnabled" class="mt-3 block"><span class="form-label">L3 工作类型 <span class="text-rose-500">*</span></span><select v-model="conversion.itemKind" class="feishu-input w-full"><option v-for="item in l3ItemKindOptions" :key="item.key" :value="item.key">{{ item.label }}</option></select></label>
                <label class="mt-3 flex items-start gap-2 rounded-lg border border-violet-100 bg-violet-50/60 px-3 py-2.5 text-[11px] text-violet-900"><input v-model="conversion.splitEnabled" type="checkbox" class="mt-0.5 rounded border-gray-300 text-accent-500" @change="toggleSplitUnits" /><span><span class="font-semibold">一条业务主线创建多个独立 L3</span><span class="mt-0.5 block leading-4 text-violet-700">所有 L3 都直接归属于当前 L2，彼此没有父子层级；共用同一张业务确认单、原始需求和价值指标，每个 L3 只补充自己的标题与差异范围。</span><span v-if="selectedItem.l3Branches?.length" class="mt-1 block font-medium text-emerald-700">已从 IT 初筛带入 {{ selectedItem.l3Branches.length }} 个独立 L3 工作项，不需要重复填写。</span></span></label>
                <div v-if="conversion.splitEnabled" class="mt-3 space-y-2 rounded-lg border border-violet-200 bg-white p-3">
                  <div class="flex items-center justify-between gap-2"><div><p class="text-[11px] font-semibold text-violet-900">独立 L3 创建清单</p><p class="mt-0.5 text-[10px] leading-4 text-violet-700">这些记录会直接创建在当前 L2 下，不生成额外的中间层；同一业务确认单的功能标准和价值指标会自动带入。</p></div><span class="text-[10px] text-violet-600">{{ conversion.splitUnits.length }} 个独立 L3</span></div>
                  <div v-for="(unit, index) in conversion.splitUnits" :key="'split-unit-' + index" class="rounded-lg border border-violet-100 bg-violet-50/30 p-2.5">
                    <div class="flex items-center justify-between gap-2"><p class="text-[11px] font-medium text-violet-900">独立 L3 工作项</p><button v-if="conversion.splitUnits.length > 2" type="button" class="text-[10px] text-rose-600" @click="removeSplitUnit(index)">移除</button></div>
                    <label class="mt-2 block"><span class="form-label">本 L3 标题 <span class="text-rose-500">*</span></span><input v-model="unit.title" class="feishu-input w-full" maxlength="300" placeholder="例如：多语言接入、售前售后角色自动切换" /></label>
                    <label class="mt-2 block"><span class="form-label">本 L3 工作类型 <span class="text-rose-500">*</span></span><select v-model="unit.itemKind" class="feishu-input w-full"><option v-for="item in l3ItemKindOptions" :key="item.key" :value="item.key">{{ item.label }}</option></select></label>
                    <label class="mt-2 block"><span class="form-label">本 L3 独有交付范围 <span class="font-normal text-gray-400">（可选）</span></span><textarea v-model="unit.scope" rows="2" maxlength="5000" class="feishu-input w-full resize-y" placeholder="只写这个独立 L3 与其他工作项不同的范围" /></label>
                    <label class="mt-2 block"><span class="form-label">本 L3 验收补充 <span class="font-normal text-gray-400">（可选）</span></span><textarea v-model="unit.acceptanceDelta" rows="2" maxlength="5000" class="feishu-input w-full resize-y" placeholder="只写这个独立 L3 特有的通过条件；通用条件已从业务确认单继承" /></label>
                  </div>
                  <button type="button" class="feishu-btn-ghost w-full justify-center text-[10px]" @click="addSplitUnit">+ 增加一个 L3</button>
                </div>
                <div v-if="conversionPhaseTemplates.length" class="mt-3 rounded-lg border border-slate-200 bg-slate-50/70 p-3"><p class="text-[11px] font-semibold text-slate-700">按 L2 类型推荐阶段（可调整）</p><div class="mt-2 grid gap-2 sm:grid-cols-2"><label v-for="phase in conversionPhaseTemplates" :key="phase.phaseKey" class="flex items-start gap-2 rounded-md border border-white bg-white px-2.5 py-2 text-[11px] text-slate-700"><input v-model="conversion.phaseTemplateKeys" :value="phase.phaseKey" type="checkbox" class="mt-0.5 rounded border-gray-300 text-accent-500" /><span><span class="font-medium">{{ phase.phaseLabel }}</span><span class="mt-0.5 block text-[10px] leading-4 text-slate-400">{{ phase.description }}</span></span></label></div></div>
              </template>
              <template v-else>
                <label class="mt-3 block"><span class="form-label">先选择已有 L2 <span class="text-rose-500">*</span></span><select v-model="conversion.projectId" class="feishu-input w-full"><option value="">请选择已有 L2</option><option v-for="project in projects" :key="project.id" :value="project.id">{{ project.name }} · {{ project.solutionTypeLabel || '待分类' }}</option></select></label>
                <label class="mt-3 block"><span class="form-label">再选择已有 L3 <span class="text-rose-500">*</span></span><select v-model="conversion.requirementId" class="feishu-input w-full" :disabled="!conversion.projectId"><option value="">{{ conversion.projectId ? '请选择该 L2 下的 L3' : '请先选择 L2' }}</option><option v-for="item in conversionRequirements" :key="item.id" :value="item.id">{{ item.title }} · {{ item.itemKindLabel || item.type }}</option></select></label>
              </template>
              <template v-if="conversion.mode !== 'link'">
                <label class="mt-3 block"><span class="form-label">开发负责人 <span class="text-rose-500">*</span></span><select v-if="developerOptions.length" v-model="conversion.assignee" class="feishu-input w-full"><option value="">请选择负责人</option><option v-for="person in developerOptions" :key="person.userId || person.name" :value="person.name">{{ person.name }}</option></select><input v-else v-model="conversion.assignee" class="feishu-input w-full" placeholder="填写开发负责人" /></label>
                <label class="mt-3 block"><span class="form-label">预计交付时间 <span class="text-rose-500">*</span></span><input v-model="conversion.expectedDeliveryTime" type="date" class="feishu-input w-full" /></label>
                <label v-if="conversion.mode === 'create'" class="mt-3 block"><span class="form-label">工作类型</span><select v-model="conversion.type" class="feishu-input w-full"><option value="新增功能">新增功能</option><option value="功能优化">功能优化</option><option value="技术建设">技术建设</option><option value="业务确认">业务确认</option><option value="验证交付">验证交付</option></select></label>
              </template>
              <div class="mt-3 rounded-lg border border-cyan-100 bg-cyan-50/60 px-3 py-2.5 text-[11px] leading-5 text-cyan-800">
                <template v-if="selectedItem.confirmation?.status === 'confirmed'"><span class="font-semibold">已确认的功能验收通过标准：</span>{{ conversion.acceptanceCriteria || '已确认，但未返回验收标准内容' }}</template>
                <template v-else><span class="font-semibold">待业务确认的上线前交付与价值口径：</span>{{ conversion.acceptanceCriteria || '请先发起上线前交付与价值确认' }}</template>
              </div>
              <div v-if="selectedItem.confirmation?.status === 'pending'" class="mt-3 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2.5 text-[11px] leading-5 text-amber-800">
                <p class="font-semibold">确认链接已生成，等待业务负责人确认</p>
                <p class="mt-1">业务确认后，“正式创建 / 关联 L2/L3”按钮才会启用；当前点击不会发起接口请求。</p>
                <div v-if="selectedItem.confirmation.link" class="mt-2 flex gap-2">
                  <input readonly :value="selectedItem.confirmation.link" class="feishu-input min-w-0 flex-1 bg-white text-[10px]" />
                  <button type="button" class="feishu-btn-ghost shrink-0 text-[10px]" @click="copyConfirmationLink(selectedItem.confirmation.link)">复制确认链接</button>
                </div>
              </div>
              <div v-else-if="selectedItem.confirmation?.status !== 'confirmed'" class="mt-3 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2.5 text-[11px] leading-5 text-amber-800">请先在左侧流程中发起上线前交付与价值确认，完成业务确认后再正式立项。</div>
              <div v-if="conversionError" class="mt-3 rounded-lg border border-amber-100 bg-amber-50/70 px-3 py-2 text-[11px] leading-5 text-amber-700">{{ conversionError }}</div>
              <button type="button" :class="['feishu-btn-primary mt-3 w-full justify-center', selectedItem.confirmation?.status !== 'confirmed' ? 'cursor-not-allowed opacity-50' : '']" :disabled="converting || selectedItem.confirmation?.status !== 'confirmed'" @click="convert">{{ converting ? '处理中...' : (conversion.mode === 'create_l2' ? '创建 L2 + 初始建设 L3' : conversion.mode === 'create' ? '在 L2 下创建 L3' : '关联已有 L3') }}</button>
              <p v-if="selectedItem.confirmation?.status !== 'confirmed'" class="mt-2 text-center text-[10px] text-gray-500">按钮灰显是流程门禁：业务确认完成后才会发送创建接口请求。</p>
              <p class="mt-3 text-[11px] leading-5 text-gray-400">完成后保留需求池、评估记录和正式 L2/L3 的关联；阶段卡会按类型写入 L3，可在 L3 详情中继续调整。</p>
            </aside>
          </div>
        </div>
      </div>
    </section>
    <div v-if="collectionManagerOpen" class="fixed inset-0 z-50 flex items-stretch justify-end bg-slate-900/40" @click.self="closeCollectionManager">
      <section role="dialog" aria-modal="true" aria-label="主动征集管理" class="flex h-full w-full max-w-6xl flex-col overflow-hidden border-l border-blue-100 bg-slate-50 shadow-2xl">
        <div class="flex items-start justify-between gap-4 border-b border-blue-100 bg-white px-5 py-4 sm:px-7">
          <div><p class="text-xs font-semibold text-blue-600">需求池 · 独立功能区</p><h2 class="mt-1 text-lg font-semibold text-gray-900">主动征集管理</h2><p class="mt-1 text-[11px] leading-5 text-gray-500">每次实际发送都会形成一个批次；业务回执先留在这里，由 IT 判断后才进入正式需求池。</p></div>
          <div class="flex shrink-0 items-center gap-2"><button type="button" class="feishu-btn-primary text-xs" @click="configureCollection">配置新的主动征集</button><button type="button" class="rounded-md px-2 py-1 text-lg leading-none text-gray-400 hover:bg-slate-100 hover:text-gray-700" aria-label="关闭" @click="closeCollectionManager">×</button></div>
        </div>
        <div class="grid min-h-0 flex-1 grid-cols-1 overflow-hidden lg:grid-cols-[330px_minmax(0,1fr)]">
          <div class="min-h-0 overflow-y-auto border-b border-gray-200 bg-white p-4 lg:border-b-0 lg:border-r sm:p-5">
            <div class="flex items-center justify-between gap-2"><div><p class="text-xs font-semibold text-gray-800">征集批次</p><p class="mt-1 text-[10px] text-gray-400">按实际发送时间记录</p></div><button type="button" class="text-[11px] text-blue-700" @click="loadCollectionBatches">刷新</button></div>
            <div v-if="collectionLoading" class="py-10 text-center text-xs text-gray-400">批次加载中...</div>
            <div v-else-if="!collectionBatches.length" class="py-10 text-center text-xs text-gray-400">还没有主动征集批次</div>
            <div v-else class="mt-3 space-y-2">
              <button v-for="batch in collectionBatches" :key="batch.id" type="button" :class="['w-full rounded-xl border p-3 text-left transition-colors', selectedCollectionBatch?.id === batch.id ? 'border-blue-300 bg-blue-50/70' : 'border-gray-100 bg-white hover:bg-slate-50']" @click="openCollectionBatch(batch.id)">
                <div class="flex items-center justify-between gap-2"><p class="truncate text-xs font-semibold text-gray-900">{{ batch.targetLabel || '指定范围' }}</p><span class="shrink-0 text-[10px] text-gray-400">{{ shortDate(batch.sentAt || batch.createdAt) }}</span></div>
                <p class="mt-1 text-[10px] text-gray-500">{{ batch.recipientCount || 0 }} 人 · 已提交 {{ batch.responseCount || 0 }} · 待判断 {{ batch.pendingCount || 0 }}</p>
                <div class="mt-2 flex flex-wrap gap-1.5 text-[10px]"><span class="rounded bg-emerald-50 px-1.5 py-0.5 text-emerald-700">有价值 {{ batch.valuableCount || 0 }}</span><span class="rounded bg-slate-100 px-1.5 py-0.5 text-slate-600">已排除 {{ batch.excludedCount || 0 }}</span><span class="text-gray-400">{{ batch.status === 'historical' ? '历史批次' : batch.status === 'success' ? '发送成功' : batch.status === 'partial' ? '部分成功' : batch.status === 'failed' ? '发送失败' : batch.status }}</span></div>
              </button>
            </div>
          </div>
          <div class="min-h-0 overflow-y-auto p-4 sm:p-6">
            <section v-if="collectionConfigOpen" class="mb-4 rounded-xl border border-blue-100 bg-white p-4 shadow-sm">
              <div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-semibold text-blue-700">新建主动征集</p><p class="mt-1 text-[11px] leading-5 text-gray-500">外部填写表单保持原样；这里仅配置发送对象、频率和说明。</p></div><button type="button" class="text-[11px] text-slate-500 hover:text-slate-800" @click="collectionConfigOpen = false">收起</button></div>
              <div v-if="notifyError" class="mt-3 rounded-lg border border-amber-100 bg-amber-50/70 px-3 py-2 text-xs leading-5 text-amber-700">{{ notifyError }}</div>
              <div class="mt-3 grid grid-cols-1 gap-3 md:grid-cols-3">
                <label class="block"><span class="form-label">发送范围</span><select v-model="notifyForm.targetType" class="feishu-input w-full"><option value="person">指定人员</option><option value="department">指定部门</option><option value="all">全员</option></select></label>
                <label v-if="notifyForm.targetType === 'person'" class="block md:col-span-2"><span class="form-label">接收人 <span class="text-rose-500">*</span></span><select v-model="notifyForm.targetUserId" class="feishu-input w-full" :disabled="contactsLoading" @focus="loadContacts()"><option value="">{{ contactsLoading ? '联系人加载中…' : (contactUsers.length ? '请选择钉钉联系人' : '暂无可选联系人，请刷新') }}</option><option v-for="person in contactUsers" :key="person.userId || person.userid || person.name" :value="person.userId || person.userid || person.dingUserId">{{ person.name }}</option></select></label>
                <label v-if="notifyForm.targetType === 'department'" class="block md:col-span-2"><span class="form-label">接收部门 <span class="text-rose-500">*</span></span><select v-model="notifyForm.targetValue" class="feishu-input w-full" :disabled="contactsLoading" @focus="loadContacts()"><option value="">{{ contactsLoading ? '部门加载中…' : '请选择部门' }}</option><option v-for="department in departmentOptions" :key="department" :value="department">{{ department }}</option></select></label>
                <div v-if="notifyForm.targetType === 'all'" class="flex items-end md:col-span-2"><p class="rounded-lg bg-gray-50 px-3 py-2 text-xs leading-5 text-gray-500">系统会通过“IT项目协作空间”机器人发送给当前通讯录中的全部可识别人员。</p></div>
              </div>
              <div class="mt-3 grid grid-cols-1 gap-3 md:grid-cols-3"><label class="block"><span class="form-label">发送频率</span><select v-model="notifyForm.scheduleCycle" class="feishu-input w-full"><option value="once">只发送一次</option><option value="daily">每天</option><option value="weekly">每周</option><option value="monthly">每月</option><option value="custom">自定义工作日</option></select></label><label v-if="notifyForm.scheduleCycle !== 'once'" class="block"><span class="form-label">发送时间</span><input v-model="notifyForm.scheduleTime" type="time" class="feishu-input w-full" /></label><label v-if="notifyForm.scheduleCycle === 'weekly' || notifyForm.scheduleCycle === 'monthly'" class="block"><span class="form-label">{{ notifyForm.scheduleCycle === 'weekly' ? '星期' : '每月几号' }}</span><select v-model.number="notifyForm.scheduleDay" class="feishu-input w-full"><option v-for="day in (notifyForm.scheduleCycle === 'weekly' ? 7 : 31)" :key="day" :value="day">{{ notifyForm.scheduleCycle === 'weekly' ? ['一','二','三','四','五','六','日'][day - 1] + '周' : day + '号' }}</option></select></label></div>
              <div v-if="notifyForm.scheduleCycle === 'custom'" class="mt-3 rounded-lg border border-blue-100 bg-blue-50/50 p-3"><div class="flex items-center justify-between"><span class="form-label">自定义发送日</span><button type="button" class="text-[11px] text-blue-700" @click="notifyForm.scheduleWeekdays = [1, 2, 3, 4, 5]">工作日</button></div><div class="mt-2 grid grid-cols-7 gap-2"><label v-for="day in ['一','二','三','四','五','六','日']" :key="day" class="flex items-center justify-center gap-1 rounded border border-blue-100 bg-white px-1 py-2 text-xs"><input v-model="notifyForm.scheduleWeekdays" :value="['一','二','三','四','五','六','日'].indexOf(day) + 1" type="checkbox" />周{{ day }}</label></div><p class="mt-2 text-[11px] text-gray-400">仅在勾选的星期发送，未勾选的周末不会推送。</p></div>
              <label class="mt-3 block"><span class="form-label">通知说明 <span class="font-normal text-gray-400">（可选）</span></span><textarea v-model="notifyForm.message" rows="3" maxlength="1000" class="feishu-input w-full resize-y" placeholder="例如：请各部门提交需要 IT 支持的流程、工具或系统想法" /></label>
              <div class="mt-3 flex flex-col-reverse gap-2 border-t border-gray-100 pt-3 sm:flex-row sm:items-center sm:justify-between"><p class="text-[11px] leading-5 text-gray-400">发送后业务回执只进入本功能区，IT 判断“有价值”后才进入需求池。</p><button type="button" class="feishu-btn-primary justify-center px-5" :disabled="sendingNotify || contactsLoading" @click="sendNotify">{{ sendingNotify ? '处理中...' : notifyForm.scheduleCycle === 'once' ? '发送主动征集' : '保存征集计划' }}</button></div>
            </section>
            <div v-if="!selectedCollectionBatch" class="flex min-h-[260px] items-center justify-center text-center text-xs text-gray-400">选择左侧批次查看回执</div>
            <template v-else>
              <div class="mb-3 rounded-xl border border-slate-100 bg-slate-50/80 p-3"><div class="flex flex-wrap items-center justify-between gap-2"><div class="grid grid-cols-2 gap-2 text-center text-[10px] sm:grid-cols-4"><div class="rounded-lg bg-white px-3 py-2"><p class="text-gray-400">钉钉已受理</p><p class="mt-1 text-sm font-semibold text-emerald-700">{{ selectedCollectionBatch.acceptedCount || selectedCollectionBatch.successCount || 0 }}</p></div><div class="rounded-lg bg-white px-3 py-2"><p class="text-gray-400">明确失败</p><p class="mt-1 text-sm font-semibold text-rose-600">{{ selectedCollectionBatch.failureCount || 0 }}</p></div><div class="rounded-lg bg-white px-3 py-2"><p class="text-gray-400">结果不确定</p><p class="mt-1 text-sm font-semibold text-amber-600">{{ selectedCollectionBatch.unknownCount || 0 }}</p></div><div class="rounded-lg bg-white px-3 py-2"><p class="text-gray-400">发送中</p><p class="mt-1 text-sm font-semibold text-blue-700">{{ selectedCollectionBatch.deliveryPendingCount || 0 }}</p></div></div><button v-if="(selectedCollectionBatch.failureCount || 0) > 0" type="button" class="rounded-md border border-amber-200 bg-white px-3 py-2 text-xs font-medium text-amber-700 hover:bg-amber-50" :disabled="collectionRetrying" @click="retryCollectionFailures">{{ collectionRetrying ? '补发中...' : '只补发明确失败' }}</button></div><p v-if="selectedCollectionBatch.unknownCount" class="mt-2 text-[11px] leading-5 text-amber-700">存在结果不确定的人员，系统不会自动补发，避免钉钉已受理后产生重复通知。</p></div>
              <div class="rounded-xl border border-blue-100 bg-white p-4 shadow-sm"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-semibold text-blue-700">征集批次详情</p><h3 class="mt-1 text-base font-semibold text-gray-900">{{ selectedCollectionBatch.targetLabel || '指定范围' }}</h3><p class="mt-1 text-[11px] text-gray-500">发送于 {{ selectedCollectionBatch.sentAt || selectedCollectionBatch.createdAt }} · {{ selectedCollectionBatch.recipientCount || 0 }} 个接收人</p></div><div class="grid grid-cols-3 gap-2 text-center text-[10px]"><div class="rounded-lg bg-slate-50 px-3 py-2"><p class="text-gray-400">已提交</p><p class="mt-1 text-sm font-semibold text-gray-900">{{ selectedCollectionBatch.responseCount || 0 }}</p></div><div class="rounded-lg bg-amber-50 px-3 py-2"><p class="text-amber-700">待判断</p><p class="mt-1 text-sm font-semibold text-amber-700">{{ selectedCollectionBatch.pendingCount || 0 }}</p></div><div class="rounded-lg bg-emerald-50 px-3 py-2"><p class="text-emerald-700">已转入</p><p class="mt-1 text-sm font-semibold text-emerald-700">{{ selectedCollectionBatch.valuableCount || 0 }}</p></div></div></div><p class="mt-3 whitespace-pre-wrap rounded-lg bg-slate-50 px-3 py-2 text-[11px] leading-5 text-gray-600">{{ selectedCollectionBatch.message || '未填写额外说明' }}</p></div>
              <section v-if="selectedCollectionBatch.deliveries?.length" class="mb-4 rounded-xl border border-gray-100 bg-white p-4 shadow-sm"><div class="flex items-center justify-between gap-2"><p class="text-xs font-semibold text-gray-800">发送明细</p><span class="text-[10px] text-gray-400">本批次接收人快照</span></div><div class="mt-3 max-h-56 space-y-1.5 overflow-y-auto"><div v-for="delivery in selectedCollectionBatch.deliveries" :key="delivery.recipientUserId" class="flex flex-wrap items-center justify-between gap-2 rounded-lg bg-slate-50 px-3 py-2 text-[11px]"><div><span class="font-medium text-gray-800">{{ delivery.recipientName || delivery.recipientUserId }}</span><span class="ml-2 text-gray-400">{{ delivery.recipientDepartment || '未标注部门' }}</span></div><div class="flex items-center gap-2"><span :class="delivery.sendStatus === 'accepted' ? 'text-emerald-600' : delivery.sendStatus === 'unknown' ? 'text-amber-600' : delivery.sendStatus === 'invalid' || delivery.sendStatus === 'failed' ? 'text-rose-600' : 'text-blue-600'">{{ delivery.sendStatus === 'accepted' ? '钉钉已受理' : delivery.sendStatus === 'unknown' ? '结果不确定' : delivery.sendStatus === 'invalid' ? '人员已失效' : delivery.sendStatus === 'failed' ? '发送失败' : delivery.sendStatus === 'sending' ? '发送中' : '待发送' }}</span><span v-if="delivery.attemptCount" class="text-gray-400">尝试 {{ delivery.attemptCount }} 次</span></div><p v-if="delivery.errorMessage" class="w-full truncate text-[10px] text-rose-500" :title="delivery.errorMessage">{{ delivery.errorCode }}：{{ delivery.errorMessage }}</p></div></div></section>
              <div class="mt-4 grid gap-4 xl:grid-cols-[minmax(0,1fr)_minmax(320px,0.85fr)]">
                <section class="rounded-xl border border-gray-100 bg-white p-4 shadow-sm"><div class="flex items-center justify-between gap-2"><p class="text-xs font-semibold text-gray-800">业务回执</p><span class="text-[10px] text-gray-400">{{ selectedCollectionBatch.responses?.length || 0 }} 条</span></div><div v-if="!selectedCollectionBatch.responses?.length" class="py-10 text-center text-xs text-gray-400">本批次还没有人提交</div><div v-else class="mt-3 space-y-2"><button v-for="response in selectedCollectionBatch.responses" :key="response.id" type="button" :class="['w-full rounded-lg border px-3 py-2.5 text-left', selectedCollectionResponse?.id === response.id ? 'border-blue-300 bg-blue-50/60' : 'border-gray-100 hover:bg-slate-50']" @click="selectCollectionResponse(response)"><div class="flex items-center justify-between gap-2"><span class="truncate text-xs font-medium text-gray-900">{{ response.recipientName || '钉钉用户' }} · {{ response.topicLabel || '其他想法' }}</span><span :class="statusClass(response.judgment === 'valuable' ? 'converted' : response.judgment === 'pending' ? 'pending_evaluation' : 'deferred')">{{ response.judgmentLabel }}</span></div><p class="mt-1 line-clamp-2 text-[11px] leading-5 text-gray-500">{{ response.problem }}</p><p class="mt-1 text-[10px] text-gray-400">{{ response.createdAt }}</p></button></div></section>
                <section v-if="selectedCollectionResponse" class="rounded-xl border border-violet-100 bg-white p-4 shadow-sm">
                  <div class="flex items-start justify-between gap-2"><div><p class="text-xs font-semibold text-violet-700">回执详情与 IT 判断</p><h3 class="mt-1 text-sm font-semibold text-gray-900">{{ selectedCollectionResponse.recipientName || '钉钉用户' }} · {{ selectedCollectionResponse.topicLabel || '其他想法' }}</h3></div><span class="text-[10px] text-gray-400">{{ selectedCollectionResponse.createdAt }}</span></div>
                  <dl class="mt-3 space-y-2 rounded-lg bg-slate-50 px-3 py-3 text-[11px] leading-5"><div><dt class="text-gray-400">归属部门</dt><dd class="whitespace-pre-wrap text-gray-700">{{ selectedCollectionResponse.department || selectedCollectionResponse.recipientDepartment || '未填写' }}</dd></div><div><dt class="text-gray-400">问题</dt><dd class="whitespace-pre-wrap text-gray-700">{{ selectedCollectionResponse.problem || selectedCollectionResponse.description }}</dd></div><div v-if="selectedCollectionResponse.frequency"><dt class="text-gray-400">发生频率</dt><dd class="text-gray-700">{{ selectedCollectionResponse.frequency }}</dd></div><div v-if="selectedCollectionResponse.desired"><dt class="text-gray-400">希望变化</dt><dd class="whitespace-pre-wrap text-gray-700">{{ selectedCollectionResponse.desired }}</dd></div></dl>
                  <div v-if="selectedCollectionResponse.attachments?.length" class="mt-3 rounded-lg border border-gray-100 px-3 py-2.5"><p class="text-[10px] font-semibold text-gray-500">附件</p><button v-for="attachment in selectedCollectionResponse.attachments" :key="attachment.id" type="button" class="mt-1 block text-[11px] text-blue-700 hover:underline" @click="downloadAttachment(attachment)">{{ attachment.originalName }}</button></div>
                  <div class="mt-4 rounded-xl border border-blue-100 bg-blue-50/60 p-3">
                    <div class="flex items-center justify-between gap-2"><p class="text-xs font-semibold text-blue-900">下一步：需求关联</p><span :class="selectedCollectionResponse.convertedDemand ? 'rounded bg-emerald-100 px-2 py-0.5 text-[10px] font-semibold text-emerald-700' : 'rounded bg-white px-2 py-0.5 text-[10px] text-blue-700'">{{ selectedCollectionResponse.convertedDemand ? '已建立关联' : '待处理' }}</span></div>
                    <div v-if="selectedCollectionResponse.convertedDemand" class="mt-2 rounded-lg border border-emerald-100 bg-white px-3 py-2.5"><p class="text-[10px] text-emerald-700">已关联需求池记录</p><p class="mt-1 text-xs font-semibold text-emerald-950">{{ selectedCollectionResponse.convertedDemand.title }}</p><p class="mt-1 text-[10px] text-emerald-700">{{ selectedCollectionResponse.convertedDemand.statusLabel || selectedCollectionResponse.convertedDemand.status }} · {{ selectedCollectionResponse.convertedDemand.id }}</p><button type="button" class="mt-2 text-[11px] font-medium text-emerald-700 hover:text-emerald-900" @click="openCollectionLinkedDemand">打开需求池详情 →</button></div>
                    <div v-else class="mt-2 space-y-2"><p v-if="collectionJudgment.judgment === 'valuable'" class="text-[11px] leading-5 text-blue-800">保存“有价值，转入需求池”后，系统会自动创建需求池记录，并在这里保留回执来源关系。</p><p v-else-if="collectionJudgment.judgment === 'duplicate'" class="text-[11px] leading-5 text-blue-800">请选择要复用的已有需求，保存后本回执会直接关联到该需求。</p><p v-else class="text-[11px] leading-5 text-blue-800">只有判断为“有价值”或“重复需求”时，才会在这里建立需求关联；其他判断只保留在主动征集记录中。</p><label v-if="collectionJudgment.judgment === 'duplicate'" class="block"><span class="form-label">选择要关联的已有需求 <span class="text-rose-500">*</span></span><select v-model="collectionJudgment.similarDemandId" class="feishu-input w-full"><option value="">请选择需求池记录</option><option v-for="demand in collectionLinkCandidates" :key="demand.id" :value="demand.id">{{ demand.title }} · {{ demand.statusLabel || demand.status }}</option></select></label></div>
                  </div>
                  <div class="mt-4 space-y-3 border-t border-gray-100 pt-3"><label class="block"><span class="form-label">IT 判断</span><select v-model="collectionJudgment.judgment" class="feishu-input w-full"><option value="">请选择判断</option><option value="valuable">有价值，转入需求池</option><option value="needs_clarification">需要补充</option><option value="duplicate">重复需求</option><option value="not_feasible">暂不可行</option><option value="not_adopted">暂不采纳</option></select></label><label class="block"><span class="form-label">判断说明 <span v-if="collectionJudgment.judgment !== 'valuable'" class="text-rose-500">*</span></span><textarea v-model="collectionJudgment.judgmentReason" rows="3" maxlength="5000" class="feishu-input w-full resize-y" placeholder="说明为什么转入、需要补充什么，或为什么暂不采纳" /></label><label class="block"><span class="form-label">下一步（可选）</span><input v-model="collectionJudgment.nextAction" maxlength="200" class="feishu-input w-full" placeholder="例如：安排业务补充现状数据" /></label><button type="button" class="feishu-btn-primary w-full justify-center text-xs" :disabled="judgingCollection || !collectionJudgmentReady" @click="judgeCollectionResponse">{{ judgingCollection ? '保存中...' : selectedCollectionResponse.convertedDemand ? '保存判断' : collectionJudgment.judgment === 'valuable' ? '判定并进入需求池' : collectionJudgment.judgment === 'duplicate' ? '判定并关联已有需求' : '保存判断' }}</button></div>
                </section>
                <section v-else class="flex min-h-[260px] items-center justify-center rounded-xl border border-dashed border-gray-200 bg-white p-4 text-center text-xs text-gray-400">点击左侧回执，查看完整内容并进行 IT 判断</section>
              </div>
            </template>
          </div>
        </div>
      </section>
    </div>
    <div v-if="pocModalOpen" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4" @click.self="closePocModal">
      <section role="dialog" aria-modal="true" aria-label="PoC / AI 验证记录" class="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl border border-violet-100 bg-white shadow-2xl">
        <div class="flex items-start justify-between gap-4 border-b border-violet-100 bg-gradient-to-r from-violet-50 via-white to-blue-50 px-5 py-4 sm:px-6">
          <div><p class="text-xs font-semibold text-violet-600">轻量登记</p><h2 class="mt-1 text-base font-semibold text-gray-900">PoC / AI 验证记录</h2><p class="mt-1 text-[11px] leading-5 text-gray-500">只留一段结论、步骤规划或附件，不需要逐项填表。</p></div>
          <button type="button" class="rounded-md px-2 py-1 text-lg leading-none text-gray-400 hover:bg-white hover:text-gray-700" aria-label="关闭" @click="closePocModal">×</button>
        </div>
        <div class="space-y-4 px-5 py-5 sm:px-6">
          <div v-if="selectedItem" class="rounded-lg border border-gray-100 bg-gray-50/70 px-3 py-2.5"><p class="text-xs font-medium text-gray-800">{{ selectedItem.title }}</p><p class="mt-1 text-[10px] text-gray-500">{{ selectedItem.solutionTypeLabel || '需求池' }} · 记录会保存到当前需求</p></div>
          <div v-if="pocModalError" class="rounded-lg border border-amber-100 bg-amber-50/70 px-3 py-2 text-xs leading-5 text-amber-700">{{ pocModalError }}</div>
